functions.updatestatus:
void updatestatus()
{

    int dt;
    int i;
    s_model *model = NULL;
    s_set_entry *set = levelsets + current_set;
    char* name = NULL;
    bool all_dead = true;
    bool hurry_time = false;

    for(i = 0; i < set->maxplayers; i++)
    {
        if(player[i].ent)
        {
            all_dead = false;
        }
        else if(player[i].joining && player[i].name[0])
        {
            model = findmodel(player[i].name);
            if((player[i].playkeys & (FLAG_START | FLAG_ATTACK) || skipselect[i][0]) && !freezeall && !nojoin)    // Can't join while animations are frozen
            {
                player[i].lives = PLAYER_LIVES;            // to address new lives settings
                player[i].joining = 0;
                player[i].hasplayed = 1;
                player[i].spawnhealth = model->health;
                player[i].spawnmp = model->mp;

                spawnplayer(i);

                execute_join_script(i);

                player[i].disablekeys = player[i].playkeys = player[i].newkeys = player[i].releasekeys = 0;

                if(!nodropen)
                {
                    drop_all_enemies();    //27-12-2004  If drop enemies is on, drop all enemies
                }

                if(!level->noreset)
                {
                    timeleft = level->settime * COUNTER_SPEED;    // Feb 24, 2005 - This line moved here to set custom time
                }

            }
            else if(player[i].playkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT))
            {
                model = ((player[i].playkeys & FLAG_MOVELEFT) ? prevplayermodeln : nextplayermodeln)(model, i);
                strcpy(player[i].name, model->name);

                player[i].colourmap = (colourselect && (set->nosame & 2)) ? nextcolourmapn(model, -1, i) : 0;

                player[i].playkeys = 0;
            }
            // don't like a characters color try a new one!
            else if(player[i].playkeys & (FLAG_MOVEUP | FLAG_MOVEDOWN))
            {
                model = ((player[i].playkeys & FLAG_MOVEUP) ? prevplayermodelcoln : nextplayermodelcoln)(model, i);
                strcpy(player[i].name, model->name);

                player[i].colourmap = (colourselect && (set->nosame & 2)) ? nextcolourmapn(model, -1, i) : 0;

                player[i].playkeys = 0;
            }
            else if (player[i].playkeys & (FLAG_JUMP | FLAG_SPECIAL) && colourselect)
            {
                player[i].colourmap = ((player[i].playkeys & FLAG_JUMP) ? nextcolourmapn : prevcolourmapn)(model, player[i].colourmap, i);

                player[i].playkeys = 0;
            }
            else if(player[i].playkeys & FLAG_ATTACK2)
            {
                model = selectrandomplayer(model);
                strcpy(player[i].name, model->name);

                player[i].colourmap = (colourselect) ? selectrandomcolourmap(model, i) : 0;

                player[i].playkeys = 0;
            }
        }
        else if( !nojoin && (player[i].credits || credits || (!player[i].hasplayed && noshare)) )
        {
            if(player[i].playkeys & FLAG_START)
            {
                int prev_color = 0;
                player[i].lives = 0;
                players[i] = 1;

                if(skipselect[i][0])
                {
                    name = skipselect[i];
                    model = findmodel(name);
                }
                else if(player[i].name[0])
                {
                    name = player[i].name;
                    model = findmodel(name);
                    prev_color = player[i].colourmap;
                }
                else
                {
                    model = nextplayermodeln(NULL, i);
                }
                if(!model && name)
                {
                    model = load_cached_model(name, "continue_screen", 3, true);
                }
                strncpy(player[i].name, model->name, MAX_NAME_LEN);

                player[i].colourmap = (colourselect && (set->nosame & 2)) ? nextcolourmapn(model, prev_color-1, i) : prev_color;

                player[i].joining = 1;
                player[i].disablekeys = player[i].playkeys = player[i].newkeys = player[i].releasekeys = 0;

                if(!level->noreset)
                {
                    timeleft = level->settime * COUNTER_SPEED;    // Feb 24, 2005 - This line moved here to set custom time
                }

                if(!player[i].hasplayed && noshare)
                {
                    player[i].credits = CONTINUES;
                }

                if(!creditscheat)
                {
                    if(noshare)
                    {
                        --player[i].credits;
                    }
                    else
                    {
                        --credits;
                    }
                    if(set->continuescore == 1)
                    {
                        player[i].score = 0;
                    }
                    if(set->continuescore == 2)
                    {
                        player[i].score = player[i].score + 1;
                    }
                }
            }
        }

        if(!player[i].ent && player[i].hasplayed && (player[i].playkeys & FLAG_ATTACK))
        {
            hurry_time = true;
            player[i].playkeys = 0;
        }
    }// end of for

    dt = timeleft / COUNTER_SPEED;

    if (hurry_time && all_dead)
    {
        timeleft = dt * COUNTER_SPEED;
    }

    if(dt >= 99)
    {
        dt      = 99;
        oldtime = 99;
    }
    if(dt <= 0)
    {
        dt      = 0;
        oldtime = 99;
    }

    if (is_total_timeover) timetoshow = 0;
    else timetoshow = dt;

    if(timetoshow < oldtime || oldtime == 0)
    {
        execute_timetick_script(timetoshow, go_time);
        oldtime = timetoshow;
    }

    if(dt > 0 && !is_total_timeover)
    {
        showtimeover = 0;
    }

    if(go_time > _time)
    {
        dt = (go_time - _time) % GAME_SPEED;

        if(dt < GAME_SPEED / 2)
        {
            showgo = 1;
            if(gosound == 0 )
            {

                if(SAMPLE_GO >= 0)
                {
                    sound_play_sample(SAMPLE_GO, 0, savedata.effectvol, savedata.effectvol, 100);    // 26-12-2004 Play go sample as arrow flashes
                }

                gosound = 1;                // 26-12-2004 Sets sample as already played - stops sample repeating too much
            }
        }
        else
        {
            showgo = gosound = 0;    //26-12-2004 Resets go sample after loop so it can be played again next time
        }
    }
    else
    {
        showgo = 0;
    }

}

