functions.load_playable_list:
static void load_playable_list(char *buf)
{
    int i, index;
    char *value;
    s_model *playermodels = NULL;
    ArgList arglist;
    char argbuf[MAX_ALLOWSELECT_LEN] = "";

    ParseArgs(&arglist, buf, argbuf);

    // avoid to load characters if there isn't an allowselect
    if ( stricmp(value = GET_ARG(0), "allowselect") != 0 ) return;

    reset_playable_list(0);

    for(i = 0; i < sizeof(argbuf); i++) allowselect_args[i] = ' ';
    for(i = 0; i < sizeof(argbuf); i++)
    {
        if ( argbuf[i] != '\0' ) allowselect_args[i] = argbuf[i]; // store allowselect players for savefile
        else allowselect_args[i] = ' ';
    }
    allowselect_args[sizeof(argbuf)-1] = '\0';

    for(i = 1; (value = GET_ARG(i))[0]; i++)
    {
        playermodels = findmodel(value);
        //if(playermodels == NULL) borShutdown(1, "Player model '%s' is not loaded.\n", value);
        index = get_cached_model_index(playermodels->name);
        if(index == -1)
        {
            borShutdown(1, "Player model '%s' is not cached.\n", value);
        }
        model_cache[index].selectable = 1;
    }

    return;
}

functions.nextcolourmap:
int nextcolourmap(s_model *model, int c)
{
    do
    {
        c++;
        if(c > model->maps_loaded)
        {
            c = 0;
        }
    }
    while(    // Keep looping until a non frozen map is found
        (model->maps.frozen > 0 && c == model->maps.frozen) ||
        (model->maps.hide_start > 0 && c >= model->maps.hide_start && c <= model->maps.hide_end)
    );

    return c;
}

functions.nextcolourmapn:
int nextcolourmapn(s_model *model, int c, int p)
{
    int color_index = nextcolourmap(model, c);
    s_set_entry *set = levelsets + current_set;

    if ( colourselect && (set->nosame & 2) )
    {
        int i = 0, j = 0;
        int maps_count = model->maps_loaded + 1;
        int used_colors_map[maps_count];
        int used_color_count = 0;

        // reset color map
        for(i = 0; i < maps_count; i++) used_colors_map[i] = 0;
        // check max color map count
        if (model->maps.frozen > 0) --maps_count;
        if (model->maps.hide_start > 0) maps_count -= model->maps.hide_end - model->maps.hide_start + 1;

        // map all used colors
        for(i = 0; i < MAX_PLAYERS; i++)
        {
            if ( p != i && stricmp(player[p].name, player[i].name) == 0 )
            {
                used_colors_map[player[i].colourmap] = 1;
                ++used_color_count;
                // all busy colors? return the next natural
                if (used_color_count >= maps_count) return color_index;
            }
        }

        // search the first free color
        for(i = color_index, j = 0; j < maps_count; j++)
        {
            if ( !used_colors_map[i] )
            {
                return i;
            }
            i = nextcolourmap(model, i);
        }
    }

    return color_index;
}

